// Concatena intro + slides + outro via montagem service
const http = require('http');

const MONTAGEM_HOST = 'montagem';
const MONTAGEM_PORT = 3000;

const body      = $input.first().json.body || $input.first().json;
const pid       = body.production_id;
const introUrl  = body.intro_url;
const slideUrls = body.slide_urls || [];
const outroUrl  = body.outro_url;

const clips = [introUrl, ...slideUrls, outroUrl].filter(Boolean);
if (clips.length < 2) throw new Error('precisa de pelo menos intro + 1 slide');

console.log(`[${pid}] Montando ${clips.length} clips...`);

function httpPost(host, port, path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const options = {
      hostname: host, port, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
    };
    const req = http.request(options, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); } });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

const r = await httpPost(MONTAGEM_HOST, MONTAGEM_PORT, '/concat', {
  clips,
  output: `${pid}/final.mp4`,
  bucket: 'cirlene-video',
});

if (r.error) throw new Error('montagem failed: ' + r.error);
console.log(`[${pid}] Montagem done: ${r.path}`);

return [{ json: { production_id: pid, final_path: r.path, final_url: r.url } }];
